      children: _jsx(_components.code, {
        className: "language-java",
        children: "public final class TesseractTsvParser {\n\n    public OcrPageLayout parse(UUID pageAssetId, int pageNumber, String tsv) {\n        List<OcrWord> words = new ArrayList<>();\n        List<OcrLine> lines = new ArrayList<>();\n\n        String[] rows = tsv.split(\"\\\\R\");\n\n        if (rows.length <= 1) {\n            return OcrPageLayout.empty(pageAssetId, pageNumber);\n        }\n\n        for (int i = 1; i < rows.length; i++) {\n            String row = rows[i];\n\n            if (row.isBlank()) {\n                continue;\n            }\n\n            String[] columns = row.split(\"\\\\t\", -1);\n\n            if (columns.length < 12) {\n                continue;\n            }\n\n            int level = Integer.parseInt(columns[0]);\n            int blockNum = Integer.parseInt(columns[2]);\n            int parNum = Integer.parseInt(columns[3]);\n            int lineNum = Integer.parseInt(columns[4]);\n            int wordNum = Integer.parseInt(columns[5]);\n\n            int left = Integer.parseInt(columns[6]);\n            int top = Integer.parseInt(columns[7]);\n            int width = Integer.parseInt(columns[8]);\n            int height = Integer.parseInt(columns[9]);\n            double confidence = Double.parseDouble(columns[10]);\n            String text = columns[11];\n\n            if (level == 5 && !text.isBlank()) {\n                words.add(new OcrWord(\n                        UUID.randomUUID(),\n                        pageNumber,\n                        blockNum,\n                        parNum,\n                        lineNum,\n                        wordNum,\n                        text,\n                        confidence / 100.0,\n                        new BoundingBox(left, top, width, height, CoordinateUnit.PIXEL, List.of())\n                ));\n            }\n        }\n\n        lines = groupWordsIntoLines(words);\n\n        return new OcrPageLayout(pageAssetId, pageNumber, lines, words);\n    }\n\n    private List<OcrLine> groupWordsIntoLines(List<OcrWord> words) {\n        return words.stream()\n                .collect(Collectors.groupingBy(\n                        word -> word.blockNumber() + \":\" + word.paragraphNumber() + \":\" + word.lineNumber(),\n                        LinkedHashMap::new,\n                        Collectors.toList()\n                ))\n                .values()\n                .stream()\n                .map(OcrLine::fromWords)\n                .toList();\n    }\n}\n"
      })
