        children: "public record OcrLine(\n        int pageNumber,\n        int blockNumber,\n        int paragraphNumber,\n        int lineNumber,\n        String text,\n        double meanConfidence,\n        BoundingBox bbox,\n        List<OcrWord> words\n) {\n    public static OcrLine fromWords(List<OcrWord> words) {\n        String text = words.stream()\n                .sorted(Comparator.comparing(w -> w.bbox().x()))\n                .map(OcrWord::text)\n                .collect(Collectors.joining(\" \"));\n\n        double confidence = words.stream()\n                .mapToDouble(OcrWord::confidence)\n                .average()\n                .orElse(-1.0);\n\n        BoundingBox bbox = BoundingBox.union(\n                words.stream().map(OcrWord::bbox).toList()\n        );\n\n        OcrWord first = words.get(0);\n\n        return new OcrLine(\n                first.pageNumber(),\n                first.blockNumber(),\n                first.paragraphNumber(),\n                first.lineNumber(),\n                text,\n                confidence,\n                bbox,\n                words\n        );\n    }\n}\n"
