        children: "public List<List<OcrWord>> groupIntoRows(List<OcrWord> words, double yTolerance) {\n    List<OcrWord> sorted = words.stream()\n            .sorted(Comparator\n                    .comparing((OcrWord w) -> w.bbox().y())\n                    .thenComparing(w -> w.bbox().x()))\n            .toList();\n\n    List<List<OcrWord>> rows = new ArrayList<>();\n\n    for (OcrWord word : sorted) {\n        Optional<List<OcrWord>> matchingRow = rows.stream()\n                .filter(row -> Math.abs(rowCenterY(row) - wordCenterY(word)) <= yTolerance)\n                .findFirst();\n\n        if (matchingRow.isPresent()) {\n            matchingRow.get().add(word);\n        } else {\n            rows.add(new ArrayList<>(List.of(word)));\n        }\n    }\n\n    rows.forEach(row -> row.sort(Comparator.comparing(w -> w.bbox().x())));\n\n    return rows;\n}\n"
