        children: "public final class FfmpegRunner {\n\n    public FfmpegRunResult run(List<String> args, Duration timeout) {\n        List<String> command = new ArrayList<>();\n        command.add(\"ffmpeg\");\n        command.addAll(args);\n\n        ProcessBuilder pb = new ProcessBuilder(command);\n        pb.redirectErrorStream(false);\n\n        Instant started = Instant.now();\n\n        try {\n            Process process = pb.start();\n\n            CompletableFuture<String> stderrFuture = CompletableFuture.supplyAsync(() ->\n                    readLimited(process.getErrorStream(), 16_000)\n            );\n\n            CompletableFuture<String> stdoutFuture = CompletableFuture.supplyAsync(() ->\n                    readLimited(process.getInputStream(), 16_000)\n            );\n\n            boolean finished = process.waitFor(timeout.toMillis(), TimeUnit.MILLISECONDS);\n\n            if (!finished) {\n                process.destroyForcibly();\n                return FfmpegRunResult.timeout(\n                        Duration.between(started, Instant.now()).toMillis()\n                );\n            }\n\n            int exitCode = process.exitValue();\n\n            return new FfmpegRunResult(\n                    exitCode,\n                    stdoutFuture.join(),\n                    stderrFuture.join(),\n                    Duration.between(started, Instant.now()).toMillis()\n            );\n\n        } catch (IOException e) {\n            throw new MediaProcessingException(\"FFMPEG_START_FAILED\", e);\n        } catch (InterruptedException e) {\n            Thread.currentThread().interrupt();\n            throw new MediaProcessingException(\"FFMPEG_INTERRUPTED\", e);\n        }\n    }\n\n    private String readLimited(InputStream input, int limit) {\n        try {\n            byte[] bytes = input.readNBytes(limit);\n            return new String(bytes, StandardCharsets.UTF_8);\n        } catch (IOException e) {\n            return \"\";\n        }\n    }\n}\n"
