ication.similarityScore(),\n                policy,\n                quality,\n                liveness\n        );\n\n        resultRepository.persistVerification(job, verification, quality, liveness, decision);\n\n        if (decision == FaceDecision.REVIEW_REQUIRED) {\n            jobRepository.markNeedsReview(job.id(), \"FACE_VERIFICATION_GRAY_ZONE\");\n        } else {\n            jobRepository.markCompleted(job.id(), decision.name());\n        }\n    }\n}\n"
